import * as fs from 'fs';
import * as path from 'path';

// BASESCAN_API_KEY は env 経由必須 (public repo に hardcode 禁止、 2026-07-27 に旧 hardcode 値を rotation 済)。
const BASESCAN_API_KEY =
  process.env.BASESCAN_API_KEY ??
  process.env.EXPLORER_API_KEY ??
  process.env.ETHERSCAN_API_KEY;
if (BASESCAN_API_KEY === undefined || BASESCAN_API_KEY === '') {
  throw new Error(
    'BASESCAN_API_KEY (or EXPLORER_API_KEY / ETHERSCAN_API_KEY) を env に設定してください。 BaseScan (https://basescan.org/myapikey) で API key を取得後、 export BASESCAN_API_KEY=<key> で実行。',
  );
}
const CHAIN_ID = '84532';
const API_URL = `https://api.etherscan.io/v2/api?chainid=${CHAIN_ID}`;

async function verifyContract(
  address: string,
  contractPath: string,
  contractName: string,
  constructorArgs: string,
) {
  console.log(`Verifying ${contractName} at ${address}...`);

  // Read build-info to get the standard JSON input
  const buildInfoDir = path.join(__dirname, '../artifacts/build-info');
  const buildInfoFiles = fs.readdirSync(buildInfoDir);

  let standardJsonInput: any = null;

  for (const file of buildInfoFiles) {
    const buildInfo = JSON.parse(fs.readFileSync(path.join(buildInfoDir, file), 'utf8'));
    if (buildInfo.output?.contracts?.[contractPath]?.[contractName]) {
      standardJsonInput = buildInfo.input;
      console.log(`Found contract in build-info: ${file}`);
      break;
    }
  }

  if (!standardJsonInput) {
    console.error('Could not find contract in build-info');
    return;
  }

  const params = new URLSearchParams({
    apikey: BASESCAN_API_KEY,
    module: 'contract',
    action: 'verifysourcecode',
    contractaddress: address,
    sourceCode: JSON.stringify(standardJsonInput),
    codeformat: 'solidity-standard-json-input',
    contractname: `${contractPath}:${contractName}`,
    compilerversion: 'v0.8.23+commit.f704f362',
    constructorArguements: constructorArgs,
  });

  const response = await fetch(API_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: params.toString(),
  });

  const result = (await response.json()) as { status: string; result: string; message: string };
  console.log('Response:', JSON.stringify(result, null, 2));

  if (result.status === '1') {
    console.log(`GUID: ${result.result}`);
    await checkVerificationStatus(result.result);
  } else {
    console.error(`Failed: ${result.result}`);
  }
}

async function checkVerificationStatus(guid: string) {
  console.log('Checking verification status...');

  for (let i = 0; i < 15; i++) {
    await new Promise(r => setTimeout(r, 5000));

    const params = new URLSearchParams({
      apikey: BASESCAN_API_KEY,
      module: 'contract',
      action: 'checkverifystatus',
      guid: guid,
    });

    const response = await fetch(`${API_URL}&${params.toString()}`);
    const result = (await response.json()) as { status: string; result: string };

    console.log(`Status check ${i + 1}:`, result.result);

    if (result.result === 'Pass - Verified') {
      console.log('✅ Verification successful!');
      return true;
    } else if (result.result.includes('Fail')) {
      console.log('❌ Verification failed');
      return false;
    }
  }
  console.log('⏳ Verification still pending...');
  return false;
}

async function main() {
  const artConstructorArgs =
    '';

  const descriptorConstructorArgs =
    '';

  console.log('=== Verifying NijiArt ===\n');
  await verifyContract(
    '0x3E5030fa5494AE86e933e6A5E38A7f8937282a11',
    'contracts/NijiArt.sol',
    'NijiArt',
    artConstructorArgs,
  );

  console.log('\n=== Verifying NijiDescriptor ===\n');
  await verifyContract(
    '0x7aD8564D0624094E45A423BCEf3007e3A8826147',
    'contracts/NijiDescriptor.sol',
    'NijiDescriptor',
    descriptorConstructorArgs,
  );
}

main().catch(console.error);
